-- Backend Engineering ("The Fracture") Act 21 -- "Testing the System" content.
-- Closes Arc V (Protect & Prove). 1 campaign, 2 operations, 12 missions (11 lessons + boss),
-- following the same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every prior Act.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be21', 'world-be-21', 'testing-the-system', '21A - Testing the System', 'A full reliability audit begins after the external-probing discovery: can anything Forge has built actually be trusted under real conditions, not just code review? The first honest test suite finds half of what the team called "tested" was run once, by hand, months ago.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be21-1', 'campaign-be21', 'foundations-of-trust', 'Foundations of Trust', 'The testing pyramid, unit tests, test doubles, integration tests, database tests and API tests -- the foundation an honest test suite is actually built on.', 1),
  ('operation-be21-2', 'campaign-be21', 'beyond-the-unit', 'Beyond the Unit', 'Contract tests, end-to-end tests, test containers, load tests, and stress and soak testing -- proving the system holds up under conditions no unit test can ever reach.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be21-01', 'world-be-21', 'campaign-be21', 'operation-be21-1', 'testing-pyramid', 'Testing Pyramid', 'A full reliability audit starts with the shape of the test suite itself, not its size. Forge''s coverage number turns out to measure something very different from what everyone assumed it measured.', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"testing-pyramid-sim"}'::jsonb, '{"xp":250,"credits":48}'::jsonb, false, 1),
  ('mission-be21-02', 'world-be-21', 'campaign-be21', 'operation-be21-1', 'unit-tests', 'Unit Tests', 'The base of the pyramid, and the cheapest test that can ever fail. A unit test earns its place by proving one small thing, in isolation, in milliseconds -- or it isn''t really a unit test at all.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be21-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"unit-tests-sim"}'::jsonb, '{"xp":252,"credits":48}'::jsonb, false, 2),
  ('mission-be21-03', 'world-be-21', 'campaign-be21', 'operation-be21-1', 'mocks-stubs-fakes', 'Mocks, Stubs, Fakes', 'Isolation is a promise a test makes about what it does and doesn''t depend on. Mocks, stubs and fakes are three different ways to keep that promise, and they are not interchangeable.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be21-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"mocks-stubs-fakes-sim"}'::jsonb, '{"xp":254,"credits":49}'::jsonb, false, 3),
  ('mission-be21-04', 'world-be-21', 'campaign-be21', 'operation-be21-1', 'integration-tests', 'Integration Tests', 'A unit test proves a function works alone. An integration test proves it still works once it has to talk to something real -- exactly where the pyramid''s next layer earns its higher cost.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be21-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"integration-tests-sim"}'::jsonb, '{"xp":256,"credits":49}'::jsonb, false, 4),
  ('mission-be21-05', 'world-be-21', 'campaign-be21', 'operation-be21-1', 'database-tests', 'Database Tests', 'The database is the one dependency almost nothing can fully fake. Testing against a real one safely means solving a problem unit tests never had to: what happens to the data after the test ends.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be21-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"database-tests-sim"}'::jsonb, '{"xp":258,"credits":49}'::jsonb, false, 5),
  ('mission-be21-06', 'world-be-21', 'campaign-be21', 'operation-be21-1', 'api-tests', 'API Tests', 'An API test doesn''t care how a handler is implemented -- only what it promises at the boundary: given this request, what response comes back. Test the promise, not the plumbing.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be21-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"api-tests-sim"}'::jsonb, '{"xp":260,"credits":50}'::jsonb, false, 6),
  ('mission-be21-07', 'world-be-21', 'campaign-be21', 'operation-be21-2', 'contract-tests', 'Contract Tests', 'Two services can each pass every test they own and still break the moment they talk to each other, if neither one ever tested the agreement between them. A contract test makes that agreement executable.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be21-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"contract-tests-sim"}'::jsonb, '{"xp":262,"credits":50}'::jsonb, false, 7),
  ('mission-be21-08', 'world-be-21', 'campaign-be21', 'operation-be21-2', 'end-to-end-tests', 'End-to-End Tests', 'The most expensive, most realistic, most fragile test in the pyramid. An end-to-end test proves the whole system works together -- when it isn''t too busy failing for reasons that have nothing to do with the bug it was written to catch.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be21-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"end-to-end-tests-sim"}'::jsonb, '{"xp":264,"credits":50}'::jsonb, false, 8),
  ('mission-be21-09', 'world-be-21', 'campaign-be21', 'operation-be21-2', 'test-containers', 'Test Containers', 'A mocked database proves your code calls the right functions. A real one, started fresh in a disposable container for every test run, proves your code survives an actual database''s actual behavior.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be21-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"test-containers-sim"}'::jsonb, '{"xp":266,"credits":51}'::jsonb, false, 9),
  ('mission-be21-10', 'world-be-21', 'campaign-be21', 'operation-be21-2', 'load-tests', 'Load Tests', 'Every test so far asked whether something works. A load test asks a different question entirely: does it still work when a thousand people ask for it in the same second, not one at a time.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be21-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"load-tests-sim"}'::jsonb, '{"xp":268,"credits":51}'::jsonb, false, 10),
  ('mission-be21-11', 'world-be-21', 'campaign-be21', 'operation-be21-2', 'stress-and-soak-testing', 'Stress and Soak Testing', 'A load test finds the edge of normal traffic. Stress testing finds the edge of the system itself. Soak testing finds the failure that only shows up hours after everything looked fine.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be21-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"stress-soak-testing-sim"}'::jsonb, '{"xp":270,"credits":52}'::jsonb, false, 11),
  ('mission-be21-12', 'world-be-21', 'campaign-be21', 'operation-be21-2', 'it-worked-on-my-machine', 'It Worked on My Machine', 'Every existing test passes. Staging fails within seconds of deploy. The gap between those two facts is the entire audit, distilled into one incident -- and the fix is not writing more of the tests Forge already had.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be21-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"worked-on-my-machine-boss-sim"}'::jsonb, '{"xp":580,"credits":135,"badgeIds":["worked-on-my-machine"],"skillXp":{"testing":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be21-01', 1, 'mira', 'The probing traffic goes into a working file behind glass for now. Before we spend another cycle chasing whoever''s on the other end, I want a harder question answered first: what in this system can we actually prove works?'),
  ('mission-be21-01', 2, 'forge', 'I pulled our test suite for a real audit, not a demo. Coverage badge said 84 percent. Then I looked at what was actually being asserted, and 84 percent quietly became a lot less honest than that number implies.'),
  ('mission-be21-01', 3, 'mira', 'Every test earns its place by proving something specific, cheaply, and constantly -- not by existing. That''s the testing pyramid: lots of cheap fast tests as the foundation, fewer expensive slow ones at the top. Get the shape wrong and you either move too slow or trust too much.'),

  ('mission-be21-02', 1, 'forge', 'Base of the pyramid. A unit test proves one function, one class, one small unit of logic behaves correctly -- completely alone, with nothing real underneath it.'),
  ('mission-be21-02', 2, 'mira', 'Alone is the whole point. The moment a "unit" test reaches out to a real database, a real network call, or the system clock, it stops being fast, stops being reliable, and stops being a unit test.'),

  ('mission-be21-03', 1, 'mira', 'Isolating a unit test means replacing what it depends on with something under your control. There are three different ways to do that, and picking the wrong one changes what the test can actually prove.'),
  ('mission-be21-03', 2, 'forge', 'A stub just answers. A mock answers and checks it was asked correctly, or the test fails. A fake is a whole simplified working version of the real thing. Use the wrong one and you either test too little or too much.'),

  ('mission-be21-04', 1, 'forge', 'Every function in this suite passes alone. None of them have ever been tested talking to the thing they actually depend on in production.'),
  ('mission-be21-04', 2, 'mira', 'That''s the gap an integration test closes -- not "does the logic work," but "does it still work once it has to cross a real boundary: a real database, a real queue, a real second service."'),

  ('mission-be21-05', 1, 'mira', 'The database is the one dependency you genuinely cannot fake all the way down. Constraints, transactions, real SQL behavior -- a mock will happily let through exactly the kind of bug a real database would reject.'),
  ('mission-be21-05', 2, 'forge', 'Test against a real one, then, but carefully. Every test that writes to a database has to leave it exactly as clean as it found it, or the next test inherits data it never created and never expected.'),

  ('mission-be21-06', 1, 'forge', 'An API test doesn''t care what''s inside the handler. It sends a real request and checks the real response -- status code, body, headers. That''s the entire contract a client actually depends on.'),
  ('mission-be21-06', 2, 'mira', 'Test the promise, not the implementation. Rewrite the handler completely tomorrow, and a good API test should not need to change at all -- only what''s returned should ever matter.'),

  ('mission-be21-07', 1, 'mira', 'Two services can each have a perfect test suite and still break in production the moment they talk to each other, if neither suite ever tested what the other one actually expects.'),
  ('mission-be21-07', 2, 'forge', 'A contract test makes that expectation explicit and automated: here is exactly the shape of request and response this integration depends on. Change the shape, and the contract test fails before a real consumer ever does.'),

  ('mission-be21-08', 1, 'forge', 'The top of the pyramid, and the most realistic test there is: a real browser, driving the real deployed system, through a real user flow, start to finish.'),
  ('mission-be21-08', 2, 'mira', 'Also the most expensive, the slowest, and the easiest to make flaky. Fewer of these than anything else in the suite -- on purpose, not from neglect.'),

  ('mission-be21-09', 1, 'mira', 'A mocked database will happily let through a bug a real one would reject on sight. Test containers exist to close that gap without giving up the speed and isolation a mock provides.'),
  ('mission-be21-09', 2, 'forge', 'A real database, in a real container, started fresh for the test run and thrown away right after. Real behavior, real constraints, and none of the cost of a shared, long-lived test database.'),

  ('mission-be21-10', 1, 'forge', 'Every test up to this point asked one request at a time whether it worked. A load test asks the much less comfortable question: does it still work at the volume this system is actually going to see.'),
  ('mission-be21-10', 2, 'mira', 'And "works" has to mean more than "the average request was fine." A system can have a perfectly good average while a meaningful slice of real users sit through something much worse.'),

  ('mission-be21-11', 1, 'mira', 'A load test proves the system handles the traffic it''s supposed to. It says nothing about what happens past that -- or what happens hours later, running fine the whole time, until it suddenly isn''t.'),
  ('mission-be21-11', 2, 'forge', 'Stress testing pushes past normal on purpose, looking for where it actually breaks. Soak testing just keeps running, for hours, looking for the failure that only shows up on a clock a load test never runs long enough to see.'),

  ('mission-be21-12', 1, 'forge', 'Full audit results are in, and the suite''s honest now: real unit tests, real integration tests, database tests against real containers, a load test, a soak test. Every one of them green for the citizen-notifications service. I signed off on it for the staging deploy myself.'),
  ('mission-be21-12', 2, 'mira', 'And?'),
  ('mission-be21-12', 3, 'forge', 'And it fails immediately in staging. Not intermittently -- immediately. Every request 500s within the first second the process comes up.'),
  ('mission-be21-12', 4, 'mira', 'Every existing test passed. So the question isn''t what''s broken. It''s what none of those tests were ever positioned to see in the first place.'),
  ('mission-be21-12', 5, 'forge', 'Three answers on the table: write more unit tests covering more of the notification logic, add a full manual QA pass before every release, or something more specific than either of those. Tell me which one, and why.'),
  ('mission-be21-12', 6, 'forge', 'Found it. A hardcoded config value -- a feature-flag service URL -- pointed at localhost in every environment, because nothing that ever tested this service ran anywhere but one laptop or one identical CI box. Staging has nothing listening on localhost. Production wouldn''t either.'),
  ('mission-be21-12', 7, 'mira', 'So the missing piece was never "more assertions." It was a test that actually ran somewhere other than the one place everything happened to already agree with itself.'),
  ('mission-be21-12', 8, 'forge', '...while I was moving every suite onto shared fixtures, I found something else. One fixture file, a path constant, untouched for over a year: "/data//archive". Every downstream test that imports it has been silently accepting a doubled slash the entire time.'),
  ('mission-be21-12', 9, 'mira', 'Does it break anything today?'),
  ('mission-be21-12', 10, 'forge', 'No. That''s what I don''t love about it. Filed, not fixed -- same shape we keep finding, and I still don''t have anywhere near enough to say what it actually means.'),
  ('mission-be21-12', 11, 'mira', 'Then it stays exactly that: filed, not chased. What we do have now, for certain -- testing proves a piece works under real conditions, one piece, one service, at a time.'),
  ('mission-be21-12', 12, 'forge', 'Whether the whole system holds up together -- under real traffic, at real scale, with all of it running at once -- is a completely different question. Right now the honest answer is: untested. Unknown.'),
  ('mission-be21-12', 13, 'mira', 'Then that''s next. Arc VI starts exactly there.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be21-01-o1', 'mission-be21-01', 1, 'Order the pyramid', 'Put the three layers of the testing pyramid in order from its base to its tip.'),
  ('mission-be21-01-o2', 'mission-be21-01', 2, 'Diagnose the coverage illusion', 'Find the evidence that explains what the audit actually found wrong with Forge''s testing, not just its coverage number.'),
  ('mission-be21-02-o1', 'mission-be21-02', 1, 'Find the isolation break', 'Debug a "unit" test that secretly reaches outside the unit it claims to test.'),
  ('mission-be21-02-o2', 'mission-be21-02', 2, 'Define a unit test', 'Choose what actually makes a test a unit test.'),
  ('mission-be21-03-o1', 'mission-be21-03', 1, 'Match the test double', 'Match each kind of test double to what it actually does.'),
  ('mission-be21-03-o2', 'mission-be21-03', 2, 'Find the missing double', 'Debug a test that uses a real dependency where a test double belonged.'),
  ('mission-be21-04-o1', 'mission-be21-04', 1, 'Find the fake integration test', 'Debug a test labeled "integration" that never actually integrates with anything real.'),
  ('mission-be21-04-o2', 'mission-be21-04', 2, 'Find what only integration catches', 'Find the evidence that shows exactly what an integration test caught that the unit tests never could.'),
  ('mission-be21-05-o1', 'mission-be21-05', 1, 'Find the test pollution', 'Debug a database test that only passes when it runs first.'),
  ('mission-be21-05-o2', 'mission-be21-05', 2, 'Choose the isolation strategy', 'Choose the approach that keeps database tests fast and isolated across runs.'),
  ('mission-be21-06-o1', 'mission-be21-06', 1, 'Find the implementation-detail assertion', 'Debug an API test that checks internals instead of the actual response contract.'),
  ('mission-be21-06-o2', 'mission-be21-06', 2, 'Define the API test''s job', 'Choose what an API test should actually assert.'),
  ('mission-be21-07-o1', 'mission-be21-07', 1, 'Find what the contract test caught', 'Find the evidence that shows what actually would have caught a breaking API change before production.'),
  ('mission-be21-07-o2', 'mission-be21-07', 2, 'Explain the consumer test''s blind spot', 'Explain why the consumer''s own integration tests missed a breaking change entirely.'),
  ('mission-be21-08-o1', 'mission-be21-08', 1, 'Find the flaky wait', 'Debug an end-to-end test that fails intermittently in CI but not locally.'),
  ('mission-be21-08-o2', 'mission-be21-08', 2, 'Explain the pyramid''s shape', 'Explain why the pyramid calls for the fewest end-to-end tests, not the most.'),
  ('mission-be21-09-o1', 'mission-be21-09', 1, 'Find what a real container catches', 'Find the evidence that shows what a real, disposable database instance catches that a mock structurally cannot.'),
  ('mission-be21-09-o2', 'mission-be21-09', 2, 'Find the resource leak', 'Debug a test container setup that never gets torn down.'),
  ('mission-be21-10-o1', 'mission-be21-10', 1, 'Diagnose the load test bottleneck', 'Find the evidence that explains the actual bottleneck behind a load test''s latency spike.'),
  ('mission-be21-10-o2', 'mission-be21-10', 2, 'Explain why percentiles matter', 'Explain why the slowest percentile of requests matters more here than the average.'),
  ('mission-be21-11-o1', 'mission-be21-11', 1, 'Distinguish stress from load', 'Choose what a stress test actually adds beyond a load test.'),
  ('mission-be21-11-o2', 'mission-be21-11', 2, 'Find what only a soak test catches', 'Find the evidence that is the actual root cause a soak test exposed and a load test structurally could not.'),
  ('mission-be21-12-o1', 'mission-be21-12', 1, 'Diagnose the staging failure', 'Find the evidence that explains the actual root cause of the staging failure, not just where it showed up.'),
  ('mission-be21-12-o2', 'mission-be21-12', 2, 'Choose the missing test category', 'Choose what would actually have caught this before staging, among several plausible-sounding answers.'),
  ('mission-be21-12-o3', 'mission-be21-12', 3, 'Trace the hardcoded value', 'Debug the exact configuration line nobody ever wrote a test to catch.'),
  ('mission-be21-12-o4', 'mission-be21-12', 4, 'Close the audit', 'Synthesize the diagnosis, the missing test category, and the exact line into what this incident actually proves.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be21-01-o1-c1', 'mission-be21-01-o1', 1, 'interactive_diagram', 'Put the three layers of the testing pyramid in order from its base (most tests, cheapest) to its tip (fewest tests, most expensive).', '{"diagramId":"testing-pyramid","hotspots":[{"id":"unit","label":"Unit tests","explanation":"Test one function or module in isolation, with no real external dependencies. Fast, cheap, and meant to be the base of the pyramid."},{"id":"integration","label":"Integration tests","explanation":"Test that two or more real pieces work together, such as a service and a real database. Slower and fewer than unit tests."},{"id":"e2e","label":"End-to-end tests","explanation":"Test a full user-facing flow through the real, deployed system. Slowest and most realistic, and meant to be the fewest tests of all."}],"task":"Put the three layers of the testing pyramid in order from its base (most tests, cheapest) to its tip (fewest tests, most expensive)."}'::jsonb, '{"correctOrderIds":["unit","integration","e2e"]}'::jsonb),
  ('mission-be21-01-o2-c1', 'mission-be21-01-o2', 1, 'investigation', 'Which evidence explains what the audit actually found wrong with the shape of Forge''s testing, not just its coverage number?', '{"evidence":[{"id":"ev1","label":"Coverage report","detail":"84% line coverage, dashboard green, badge passing on every pull request."},{"id":"ev2","label":"Test suite audit","detail":"Of the suite''s 340 test files, 6 are automated end-to-end tests, 1 is an automated integration test, and most of the rest only import a module and assert that it does not throw."},{"id":"ev3","label":"Team interview","detail":"Most engineers say the real verification for a feature happens by clicking through it manually before a release, not through any automated suite."}],"question":"Which evidence explains what the audit actually found wrong with the shape of Forge''s testing, not just its coverage number?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be21-02-o1-c1', 'mission-be21-02-o1', 1, 'code_debugging', 'This is supposed to be a unit test for calculateShippingCost. Which line breaks the isolation a unit test is supposed to guarantee?', '{"language":"javascript","code":"function calculateShippingCost(order) {\n  return order.weight * 2.5;\n}\n\ntest(\"calculates shipping cost\", () => {\n  const db = connectToProductionDatabase();\n  const order = db.getOrder(482);\n  expect(calculateShippingCost(order)).toBe(12.5);\n});","question":"This is supposed to be a unit test for calculateShippingCost. Which line breaks the isolation a unit test is supposed to guarantee?"}'::jsonb, '{"requiredLineIds":["  const db = connectToProductionDatabase();"]}'::jsonb),
  ('mission-be21-02-o2-c1', 'mission-be21-02-o2', 1, 'multiple_choice', 'What actually makes a test a "unit" test?', '{"question":"What actually makes a test a \"unit\" test?","options":[{"id":"a","text":"It only tests one file, regardless of what''s inside it"},{"id":"b","text":"It has exactly one assert statement"},{"id":"c","text":"It exercises a single unit of logic in isolation, with no real external dependencies, and runs in milliseconds"},{"id":"d","text":"It runs before the integration tests in file order"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),

  ('mission-be21-03-o1-c1', 'mission-be21-03-o1', 1, 'drag_and_drop', 'Match each kind of test double to what it actually does.', '{"items":[{"id":"m1","text":"Stub"},{"id":"m2","text":"Mock"},{"id":"m3","text":"Fake"},{"id":"m4","text":"Spy"}],"targets":[{"id":"t1","label":"Returns a canned answer when called, with no interest in whether or how it was called"},{"id":"t2","label":"A pre-programmed object that also verifies specific calls were made, with the right arguments, and fails the test if they weren''t"},{"id":"t3","label":"A working, simplified implementation usable in place of the real dependency"},{"id":"t4","label":"Wraps a real object and records how it was called, without changing its behavior"}]}'::jsonb, '{"correctMapping":{"m1":"t1","m2":"t2","m3":"t3","m4":"t4"}}'::jsonb),
  ('mission-be21-03-o2-c1', 'mission-be21-03-o2', 1, 'code_debugging', 'Every run of this test sends a real email through a live SendGrid account. Which line is where a test double needed to replace the real dependency?', '{"language":"javascript","code":"test(\"sends a welcome email on signup\", () => {\n  const emailer = new SendGridClient(realApiKey);\n  const result = signUpUser({ email: \"test@example.com\" }, emailer);\n  expect(result.success).toBe(true);\n});","question":"Every run of this test sends a real email through a live SendGrid account. Which line is where a test double needed to replace the real dependency?"}'::jsonb, '{"requiredLineIds":["  const emailer = new SendGridClient(realApiKey);"]}'::jsonb),

  ('mission-be21-04-o1-c1', 'mission-be21-04-o1', 1, 'code_debugging', 'This is labeled an integration test for the database layer, but it never actually touches a database. Which line is where it quietly became a unit test wearing an integration test''s name?', '{"language":"javascript","code":"test(\"saves an order to the database\", async () => {\n  const db = { save: jest.fn().mockResolvedValue({ id: 1 }) };\n  const result = await saveOrder(db, { item: \"widget\" });\n  expect(result.id).toBe(1);\n});","question":"This is labeled an integration test for the database layer, but it never actually touches a database. Which line is where it quietly became a unit test wearing an integration test''s name?"}'::jsonb, '{"requiredLineIds":["  const db = { save: jest.fn().mockResolvedValue({ id: 1 }) };"]}'::jsonb),
  ('mission-be21-04-o2-c1', 'mission-be21-04-o2', 1, 'investigation', 'Which evidence shows exactly what only the integration test could have caught?', '{"evidence":[{"id":"ev1","label":"Unit test result","detail":"saveOrder''s unit tests, run against a mocked db.save, all pass."},{"id":"ev2","label":"Integration test result","detail":"The same call against a real Postgres instance fails: the orders table has a NOT NULL constraint on customer_id that saveOrder never sets."},{"id":"ev3","label":"Code review","detail":"saveOrder''s function signature never required a customer_id argument in the first place."}],"question":"Which evidence shows exactly what only the integration test could have caught?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be21-05-o1-c1', 'mission-be21-05-o1', 1, 'code_debugging', 'This test passes alone and fails whenever it runs after any other test that also inserted a user. Which line assumes an isolation the test never actually established?', '{"language":"javascript","code":"test(\"creates a user\", async () => {\n  await db.query(\"INSERT INTO users (email) VALUES ($1)\", [\"a@example.com\"]);\n  const count = await db.query(\"SELECT COUNT(*) FROM users\");\n  expect(count.rows[0].count).toBe(\"1\");\n});","question":"This test passes alone and fails whenever it runs after any other test that also inserted a user. Which line assumes an isolation the test never actually established?"}'::jsonb, '{"requiredLineIds":["  const count = await db.query(\"SELECT COUNT(*) FROM users\");"]}'::jsonb),
  ('mission-be21-05-o2-c1', 'mission-be21-05-o2', 1, 'multiple_choice', 'Which approach keeps database tests fast and isolated across runs?', '{"question":"Which approach keeps database tests fast and isolated across runs?","options":[{"id":"a","text":"Wrap each test in a transaction and roll it back at the end, so nothing it writes ever persists"},{"id":"b","text":"Delete every row from every table once, before the whole suite starts"},{"id":"c","text":"Run the tests in a random order so pollution shows up eventually"},{"id":"d","text":"Share one long-lived row across every test to save on setup time"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-be21-06-o1-c1', 'mission-be21-06-o1', 1, 'code_debugging', 'This is supposed to be an API test for GET /api/orders/1. Which line tests an internal implementation detail instead of the actual response the client receives?', '{"language":"javascript","code":"test(\"GET /api/orders/1 returns the order\", async () => {\n  const spy = jest.spyOn(orderService, \"fetchFromCache\");\n  await request(app).get(\"/api/orders/1\");\n  expect(spy).toHaveBeenCalled();\n});","question":"This is supposed to be an API test for GET /api/orders/1. Which line tests an internal implementation detail instead of the actual response the client receives?"}'::jsonb, '{"requiredLineIds":["  expect(spy).toHaveBeenCalled();"]}'::jsonb),
  ('mission-be21-06-o2-c1', 'mission-be21-06-o2', 1, 'multiple_choice', 'What should an API test actually assert?', '{"question":"What should an API test actually assert?","options":[{"id":"a","text":"Which internal functions were called to build the response"},{"id":"b","text":"The response status code and body shape a real client will actually receive, given a real request"},{"id":"c","text":"How many database rows exist afterward"},{"id":"d","text":"The size of the compiled server bundle"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be21-07-o1-c1', 'mission-be21-07-o1', 1, 'investigation', 'Which evidence explains what actually would have caught this before it reached production?', '{"evidence":[{"id":"ev1","label":"Provider changelog","detail":"The /api/orders response renamed its field from total to totalAmount in the latest release."},{"id":"ev2","label":"Consumer integration test","detail":"The billing service''s own tests, run against its own mocked copy of the orders API, all still pass."},{"id":"ev3","label":"Contract test result","detail":"A contract test run against the orders service''s real, current response fails: totalAmount is missing the field consumers actually expect, total."}],"question":"Which evidence explains what actually would have caught this before it reached production?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),
  ('mission-be21-07-o2-c1', 'mission-be21-07-o2', 1, 'multiple_choice', 'Why did the consumer''s own integration tests (ev2) miss this entirely?', '{"question":"Why did the consumer''s own integration tests (ev2) miss this entirely?","options":[{"id":"a","text":"They were never run in CI"},{"id":"b","text":"They test against a mocked copy of the provider that no longer matches its real, current response shape"},{"id":"c","text":"Integration tests cannot test HTTP responses"},{"id":"d","text":"The consumer has no automated tests at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be21-08-o1-c1', 'mission-be21-08-o1', 1, 'code_debugging', 'This end-to-end test passes locally and fails intermittently in CI. Which line is the actual source of the flakiness?', '{"language":"javascript","code":"test(\"checkout completes successfully\", async () => {\n  await page.click(\"#submit-order\");\n  await page.waitForTimeout(2000);\n  const confirmation = await page.textContent(\"#confirmation\");\n  expect(confirmation).toContain(\"Order confirmed\");\n});","question":"This end-to-end test passes locally and fails intermittently in CI. Which line is the actual source of the flakiness?"}'::jsonb, '{"requiredLineIds":["  await page.waitForTimeout(2000);"]}'::jsonb),
  ('mission-be21-08-o2-c1', 'mission-be21-08-o2', 1, 'multiple_choice', 'Why does the pyramid call for the fewest end-to-end tests, not the most?', '{"question":"Why does the pyramid call for the fewest end-to-end tests, not the most?","options":[{"id":"a","text":"They are difficult to write correctly"},{"id":"b","text":"They are slow, expensive to maintain, and when one fails it only tells you something broke somewhere in the whole system, not where"},{"id":"c","text":"They cannot catch real bugs"},{"id":"d","text":"They require a graphical browser to exist"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be21-09-o1-c1', 'mission-be21-09-o1', 1, 'investigation', 'Which evidence shows what a real, disposable database instance catches that a mock structurally cannot?', '{"evidence":[{"id":"ev1","label":"Mocked-DB test suite","detail":"saveOrder''s tests all pass against an in-memory mock with no unique constraints, foreign keys, or real SQL dialect."},{"id":"ev2","label":"Production incident","detail":"A unique constraint violation in the real Postgres database caused a 500 error the mocked test suite could never have caught."},{"id":"ev3","label":"Test container run","detail":"The same test suite, run against a real Postgres instance started fresh in a container for the run, fails on the exact constraint the mock silently allowed through."}],"question":"Which evidence shows what a real, disposable database instance catches that a mock structurally cannot?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),
  ('mission-be21-09-o2-c1', 'mission-be21-09-o2', 1, 'code_debugging', 'This file starts a fresh container in beforeAll but never stops it anywhere -- after a few hundred CI runs, new containers stop starting at all. Which line is the one resource this entire file leaks?', '{"language":"typescript","code":"let container;\nlet db;\n\nbeforeAll(async () => {\n  container = await new PostgreSqlContainer().start();\n  db = await connect(container.getConnectionUri());\n});\n\ntest(\"saves an order\", async () => {\n  const result = await saveOrder(db, { item: \"widget\" });\n  expect(result.id).toBeDefined();\n});","question":"This file starts a fresh container in beforeAll but never stops it anywhere -- after a few hundred CI runs, new containers stop starting at all. Which line is the one resource this entire file leaks?"}'::jsonb, '{"requiredLineIds":["  container = await new PostgreSqlContainer().start();"]}'::jsonb),

  ('mission-be21-10-o1-c1', 'mission-be21-10-o1', 1, 'investigation', 'Which evidence explains the actual bottleneck behind the p99 latency spike, not just a symptom of it?', '{"evidence":[{"id":"ev1","label":"Load test summary","detail":"At 200 requests per second, median response time is 40ms, but p99 response time is 4200ms."},{"id":"ev2","label":"CPU graph","detail":"CPU utilization across every instance stays under 30% for the entire test."},{"id":"ev3","label":"Connection pool config","detail":"The database connection pool is configured with a maximum of 10 connections, shared across every instance."}],"question":"Which evidence explains the actual bottleneck behind the p99 latency spike, not just a symptom of it?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),
  ('mission-be21-10-o2-c1', 'mission-be21-10-o2', 1, 'multiple_choice', 'Why does the p99 number in the load test summary matter more here than the median?', '{"question":"Why does the p99 number in the load test summary matter more here than the median?","options":[{"id":"a","text":"It doesn''t -- the median is what most users actually feel"},{"id":"b","text":"The median hides how badly the slowest fraction of real users are being treated, and that is usually exactly where the real bottleneck shows up first"},{"id":"c","text":"p99 is only meaningful during a load test, never in production"},{"id":"d","text":"Percentiles are simply less accurate than an average"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be21-11-o1-c1', 'mission-be21-11-o1', 1, 'multiple_choice', 'A load test confirms the system handles its normal expected traffic. What does a stress test add that a load test does not answer?', '{"question":"A load test confirms the system handles its normal expected traffic. What does a stress test add that a load test does not answer?","options":[{"id":"a","text":"Nothing -- they test exactly the same thing"},{"id":"b","text":"It pushes traffic on purpose past normal levels, to find where and how the system actually breaks"},{"id":"c","text":"It only exercises error pages, never real ones"},{"id":"d","text":"It removes the need for any monitoring afterward"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be21-11-o2-c1', 'mission-be21-11-o2', 1, 'investigation', 'Which evidence is the actual root cause the soak test exposed, not just proof that something eventually failed?', '{"evidence":[{"id":"ev1","label":"Load test result","detail":"A one-hour load test at normal traffic shows stable memory and no errors."},{"id":"ev2","label":"Soak test result","detail":"The same service, run continuously for 18 hours at normal traffic, shows memory usage climbing steadily and unrecoverably until the process is killed and restarted."},{"id":"ev3","label":"Code review","detail":"A caching layer adds an entry on every request but never evicts or expires any of them."}],"question":"Which evidence is the actual root cause the soak test exposed, not just proof that something eventually failed?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be21-12-o1-c1', 'mission-be21-12-o1', 1, 'investigation', 'Which evidence explains the actual root cause of the staging failure, not just where it showed up?', '{"evidence":[{"id":"ev1","label":"Test suite result","detail":"Every unit, integration, contract, load and soak test for the citizen-notifications service passes in CI."},{"id":"ev2","label":"Staging deploy log","detail":"The process starts, then every request immediately fails with a connection error to the feature-flag service."},{"id":"ev3","label":"Config diff","detail":"The feature-flag service URL is hardcoded to http://localhost:9200 in the service''s config, and every test environment the service has ever run in, including CI, happens to run a feature-flag service on localhost too."}],"question":"Which evidence explains the actual root cause of the staging failure, not just where it showed up?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),
  ('mission-be21-12-o2-c1', 'mission-be21-12-o2', 1, 'multiple_choice', 'Every existing test passed. What would actually have caught this before staging?', '{"question":"Every existing test passed. What would actually have caught this before staging?","options":[{"id":"a","text":"More unit tests covering more of the notification-formatting logic"},{"id":"b","text":"A full manual QA click-through before every release"},{"id":"c","text":"An integration or contract test run against a staging-equivalent environment configuration, so a hardcoded localhost value fails the same way it would in staging"},{"id":"d","text":"A higher code coverage threshold enforced in CI"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-be21-12-o3-c1', 'mission-be21-12-o3', 1, 'code_debugging', 'Which line is the environment-specific value nobody ever wrote a test to catch?', '{"language":"typescript","code":"const config = {\n  featureFlagServiceUrl: \"http://localhost:9200\",\n  notificationQueue: process.env.NOTIFICATION_QUEUE_URL,\n  retryLimit: 3,\n};","question":"Which line is the environment-specific value nobody ever wrote a test to catch?"}'::jsonb, '{"requiredLineIds":["  featureFlagServiceUrl: \"http://localhost:9200\","]}'::jsonb),
  ('mission-be21-12-o4-c1', 'mission-be21-12-o4', 1, 'boss_encounter', 'Having diagnosed the failure, chosen the missing test category, and traced the exact line, state what this incident actually proves.', '{"stages":[{"objectiveRef":"mission-be21-12-o1","label":"Diagnose the staging failure"},{"objectiveRef":"mission-be21-12-o2","label":"Choose the missing test category"},{"objectiveRef":"mission-be21-12-o3","label":"Trace the hardcoded value"}],"task":"Having diagnosed the failure, chosen the missing test category, and traced the exact line, state what this incident actually proves: the suite needed a test that runs against a real, staging-equivalent environment configuration -- not more unit tests, and not a manual QA pass."}'::jsonb, '{"requiredObjectiveIds":["mission-be21-12-o1","mission-be21-12-o2","mission-be21-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be21-01-o1-c1', 'orientation', 'Fewer, slower tests belong near the top; more, faster tests belong near the bottom.', 10, 1),
  ('mission-be21-01-o1-c1', 'concept', 'A test that talks to a real browser and a live deployment can never run as often, or as cheaply, as one that only calls a function directly.', 20, 2),
  ('mission-be21-01-o1-c1', 'solution', 'Unit tests form the base, integration tests sit in the middle, end-to-end tests sit at the very top.', 30, 3),
  ('mission-be21-01-o2-c1', 'orientation', 'A high coverage number only says lines were executed -- it says nothing about whether anything meaningful was actually checked.', 10, 1),
  ('mission-be21-01-o2-c1', 'concept', 'A test that merely imports a module and asserts it does not throw counts toward coverage without proving the module does anything correctly.', 20, 2),
  ('mission-be21-01-o2-c1', 'solution', 'ev3: most of what the team called "tested" was really verified by a person clicking through it by hand, not by the automated suite the coverage badge describes.', 30, 3),

  ('mission-be21-02-o1-c1', 'orientation', 'A unit test is supposed to need nothing outside the function itself.', 10, 1),
  ('mission-be21-02-o1-c1', 'concept', 'The moment a test reaches an actual database, it inherits every failure mode of that database -- speed, availability, existing data -- none of which the function under test controls.', 20, 2),
  ('mission-be21-02-o1-c1', 'solution', 'connectToProductionDatabase() is the line that breaks isolation -- everything downstream of it depends on a real, shared, external system.', 30, 3),
  ('mission-be21-02-o2-c1', 'orientation', 'Speed and isolation are both symptoms of the same underlying property.', 10, 1),
  ('mission-be21-02-o2-c1', 'solution', 'c: a real unit test exercises one unit of logic alone, with nothing real underneath it, and runs in milliseconds because of it.', 20, 2),

  ('mission-be21-03-o1-c1', 'orientation', 'One of these checks how it was called and fails the test if it wasn''t. One just answers. One is a real, working, simplified implementation.', 10, 1),
  ('mission-be21-03-o1-c1', 'concept', 'A spy is the only one of the four that wraps something real instead of replacing it outright.', 20, 2),
  ('mission-be21-03-o1-c1', 'solution', 'Stub -> canned answer, no verification. Mock -> canned answer plus verifies the call. Fake -> a real, simplified working implementation. Spy -> wraps the real thing and records calls.', 30, 3),
  ('mission-be21-03-o2-c1', 'orientation', 'Nothing in this test is supposed to reach a live third-party service at all.', 10, 1),
  ('mission-be21-03-o2-c1', 'solution', 'new SendGridClient(realApiKey) is the real dependency -- a stub or mock standing in for the emailer would remove the live call entirely.', 20, 2),

  ('mission-be21-04-o1-c1', 'orientation', 'Nothing in this test ever leaves the process it runs in.', 10, 1),
  ('mission-be21-04-o1-c1', 'concept', 'jest.fn().mockResolvedValue(...) replaces the real database call outright -- the test can never fail the way a real database call could.', 20, 2),
  ('mission-be21-04-o1-c1', 'solution', 'const db = { save: jest.fn().mockResolvedValue({ id: 1 }) } is a mock standing in for the entire database -- this is a unit test, not an integration test.', 30, 3),
  ('mission-be21-04-o2-c1', 'orientation', 'The unit test result and the code review both describe the code in isolation. One piece of evidence describes what happened when it met something real.', 10, 1),
  ('mission-be21-04-o2-c1', 'solution', 'ev2: only the integration test, run against a real database with a real NOT NULL constraint, actually surfaced the missing customer_id.', 20, 2),

  ('mission-be21-05-o1-c1', 'orientation', 'This test never removes the row it inserts, and never checks whether the table was empty beforehand.', 10, 1),
  ('mission-be21-05-o1-c1', 'concept', 'A test that counts rows is really asserting how many other tests have run before it, not how many rows this test itself created.', 20, 2),
  ('mission-be21-05-o1-c1', 'solution', 'The count assertion assumes the users table started empty -- an assumption this test never actually establishes or enforces.', 30, 3),
  ('mission-be21-05-o2-c1', 'orientation', 'Whatever the strategy, it has to guarantee the database looks identical before every single test, not just at the start of the suite.', 10, 1),
  ('mission-be21-05-o2-c1', 'solution', 'a: wrapping each test in a transaction and rolling it back afterward means nothing a test writes can ever leak into the next one.', 20, 2),

  ('mission-be21-06-o1-c1', 'orientation', 'A client calling this endpoint over HTTP has no way to observe which internal function got called.', 10, 1),
  ('mission-be21-06-o1-c1', 'concept', 'Spying on an internal method couples the test to today''s implementation -- refactor fetchFromCache away entirely and this test breaks even if the endpoint still works perfectly.', 20, 2),
  ('mission-be21-06-o1-c1', 'solution', 'expect(spy).toHaveBeenCalled() tests an implementation detail the client never sees -- the actual response was never even asserted.', 30, 3),
  ('mission-be21-06-o2-c1', 'orientation', 'A client only ever sees what crosses the boundary -- nothing that happens behind it.', 10, 1),
  ('mission-be21-06-o2-c1', 'solution', 'b: an API test should assert the status code and body shape a real client actually receives, nothing about how the server got there.', 20, 2),

  ('mission-be21-07-o1-c1', 'orientation', 'The consumer''s own integration test is testing against a version of the provider that no longer exists.', 10, 1),
  ('mission-be21-07-o1-c1', 'concept', 'A contract test run against the provider''s real, current shape is the only one of these that reflects reality at the moment it runs.', 20, 2),
  ('mission-be21-07-o1-c1', 'solution', 'ev3: the contract test, run against the orders service''s actual current response, is what actually surfaces the missing field before a real consumer does.', 30, 3),
  ('mission-be21-07-o2-c1', 'orientation', 'Ask what the mock in the consumer''s test suite was built from, and when.', 10, 1),
  ('mission-be21-07-o2-c1', 'solution', 'b: the consumer''s tests run against its own mocked copy of the provider, and nothing updates that mock when the real provider changes.', 20, 2),

  ('mission-be21-08-o1-c1', 'orientation', 'A fixed wait assumes the page always takes exactly this long -- it never actually checks that the confirmation is ready.', 10, 1),
  ('mission-be21-08-o1-c1', 'concept', 'Under load or on a slower CI runner, 2000ms may not be enough; on a fast run it wastes time waiting for something already finished.', 20, 2),
  ('mission-be21-08-o1-c1', 'solution', 'page.waitForTimeout(2000) waits a fixed amount of time instead of waiting for the actual confirmation element to appear -- that is the flakiness.', 30, 3),
  ('mission-be21-08-o2-c1', 'orientation', 'Think about what breaks a build when one of these fails, versus what it actually tells you about where the bug is.', 10, 1),
  ('mission-be21-08-o2-c1', 'solution', 'b: end-to-end tests are the slowest and most fragile, and a failure only says something is wrong somewhere in the whole system, not where -- that cost is why the pyramid keeps them rare.', 20, 2),

  ('mission-be21-09-o1-c1', 'orientation', 'A mock only enforces the rules you remembered to give it. A real database enforces its own rules regardless.', 10, 1),
  ('mission-be21-09-o1-c1', 'solution', 'ev3: the test container run against a real Postgres instance is the only one of these that actually enforces the constraint the mock silently let through.', 20, 2),
  ('mission-be21-09-o2-c1', 'orientation', 'Every beforeAll here starts something. Look for what should be stopped, and where the file that should stop it is missing.', 10, 1),
  ('mission-be21-09-o2-c1', 'concept', 'A container that''s never stopped keeps consuming Docker resources long after the test file finishes -- and there is no afterAll anywhere in this file.', 20, 2),
  ('mission-be21-09-o2-c1', 'solution', 'container = await new PostgreSqlContainer().start() is the resource this file starts and never releases -- it needs a matching container.stop() in an afterAll.', 30, 3),

  ('mission-be21-10-o1-c1', 'orientation', 'Low CPU usage under load rules out the most obvious suspect.', 10, 1),
  ('mission-be21-10-o1-c1', 'concept', 'A connection pool capped far below the actual traffic level forces requests to queue for a connection -- CPU stays idle while requests simply wait their turn.', 20, 2),
  ('mission-be21-10-o1-c1', 'solution', 'ev3: a 10-connection pool shared across every instance is the actual bottleneck -- the CPU headroom in ev2 rules out compute as the cause.', 30, 3),
  ('mission-be21-10-o2-c1', 'orientation', 'An average can look perfectly healthy while a meaningful slice of real requests are having a much worse time.', 10, 1),
  ('mission-be21-10-o2-c1', 'solution', 'b: the median hides exactly the users the p99 number reveals -- and that slowest slice is usually where the real bottleneck shows up first.', 20, 2),

  ('mission-be21-11-o1-c1', 'orientation', 'A load test confirms behavior at a known traffic level. A stress test is interested in what happens past that level entirely.', 10, 1),
  ('mission-be21-11-o1-c1', 'solution', 'b: a stress test deliberately pushes past normal traffic to find where, and how, the system actually breaks.', 20, 2),
  ('mission-be21-11-o2-c1', 'orientation', 'The load test and the soak test both describe symptoms over time. One piece of evidence explains why the symptom exists at all.', 10, 1),
  ('mission-be21-11-o2-c1', 'concept', 'Memory that only grows, and is never released, is the signature of something being added on every request with nothing ever removing it.', 20, 2),
  ('mission-be21-11-o2-c1', 'solution', 'ev3: a cache that adds an entry per request and never evicts anything is the actual root cause -- the soak test just ran long enough for that to become visible.', 30, 3),

  ('mission-be21-12-o1-c1', 'orientation', 'Two pieces of evidence describe the failure. One explains why every test environment happened to agree with a value that was never actually correct.', 10, 1),
  ('mission-be21-12-o1-c1', 'concept', 'A hardcoded value that happens to be right in every place a test has ever run is indistinguishable from a correct value, until it runs somewhere new.', 20, 2),
  ('mission-be21-12-o1-c1', 'solution', 'ev3: the feature-flag URL is hardcoded to localhost, and every environment this service has ever been tested in -- including CI -- happened to have a feature-flag service on localhost too.', 30, 3),
  ('mission-be21-12-o2-c1', 'orientation', 'Two of these answers just mean writing more of exactly the kind of test that already passed.', 10, 1),
  ('mission-be21-12-o2-c1', 'solution', 'c: only a test that actually runs against a staging-equivalent configuration would have made the hardcoded localhost value fail the same way it fails in staging.', 20, 2),
  ('mission-be21-12-o3-c1', 'orientation', 'One of these three values is the only one that is not meant to change between environments -- and shouldn''t be.', 10, 1),
  ('mission-be21-12-o3-c1', 'solution', 'featureFlagServiceUrl: "http://localhost:9200" is hardcoded rather than read from the environment, unlike notificationQueue right below it.', 20, 2),
  ('mission-be21-12-o4-c1', 'orientation', 'Line up the root cause, the missing test category, and the exact line into one statement, not three separate answers.', 15, 1),
  ('mission-be21-12-o4-c1', 'solution', 'The suite was missing a test that actually runs against a staging-equivalent environment configuration -- that is what would have caught the hardcoded localhost value before staging did, and it is not solved by more unit tests or a manual QA pass.', 25, 2);
